// Read-only browser fixtures generated by test-category-marker-sync-local.php.
// Requires Playwright with Chromium/WebKit. Run the PHP fixture test first.
const {chromium,webkit}=require('playwright');
const {readFileSync}=require('node:fs');
const assert=require('node:assert/strict');
const dir=require('node:os').tmpdir();
(async()=>{
for(const [name,engine] of [['chromium',chromium],['webkit',webkit]]) {
 const browser=await engine.launch({headless:true});
 try {
 const context=await browser.newContext({ignoreHTTPSErrors:true,viewport:{width:1200,height:900}});
 await context.route('**/__codex-category-*/',route=>{const type=route.request().url().includes('-edit/')?'edit':'add';return route.fulfill({contentType:'text/html',body:readFileSync(dir+'/icts-category-'+type+'-fixture.html','utf8')});});
 const page=await context.newPage(); const errors=[];page.on('pageerror',e=>errors.push(e.message));
 for(const type of ['add','edit']) {
  await page.goto('https://iesaero.local/__codex-category-'+type+'/',{waitUntil:'networkidle'});
  const button=page.getByRole('combobox');await button.waitFor();
  const native=page.locator('select[name="icts_category_color_slug"]');
  assert.equal(await native.inputValue(),type==='edit'?'brand-primary':'');
  await button.click();
  assert.equal(await page.getByRole('option').count(),31);
  const colors=await page.getByRole('option').evaluateAll(items=>items.map(i=>getComputedStyle(i.querySelector('.icts-category-colour-swatch > span')).backgroundColor));
  assert.ok(colors.every(c=>c!=='rgba(0, 0, 0, 0)'));
  await page.getByRole('option',{name:'Green',exact:true}).click();assert.equal(await native.inputValue(),'green');
  assert.equal(await page.locator('form').evaluate(f=>new FormData(f).get('icts_category_color_slug')),'green');
  await button.press('Enter');await button.press('Home');await button.press('Escape');assert.equal(await native.inputValue(),'green');
  await button.press('Enter');await button.press('Home');await button.press('Enter');assert.equal(await native.inputValue(),'');
  await button.press('s');await button.press('l');await button.press('a');await button.press('Enter');assert.equal(await native.inputValue(),'slate');
  await button.press('Enter');await button.press('End');await button.press('ArrowUp');await button.press('Tab');assert.equal(await native.inputValue(),'tertiary');
  await button.click();await page.getByRole('heading',{name:'Categories',exact:true}).click();assert.equal(await button.getAttribute('aria-expanded'),'false');
  if(type==='add'){await page.getByRole('button',{name:'Reset',exact:true}).click();await page.waitForTimeout(50);assert.equal(await native.inputValue(),'');}
  const column=await page.locator('.icts-category-colour-value .icts-category-colour-swatch > span').evaluateAll(items=>items.map(i=>getComputedStyle(i).backgroundColor));
  assert.deepEqual(column,['rgb(0, 53, 101)','rgb(193, 10, 39)']);
  await button.click();await page.screenshot({path:'/tmp/icts-swatches-'+name+'-'+type+'.png'});await button.press('Escape');
  await page.setViewportSize({width:390,height:844});await button.click();
  const box=await page.getByRole('listbox').boundingBox();assert.ok(box.x>=0&&box.x+box.width<=390&&box.y>=0&&box.y+box.height<=845);
  await page.getByRole('option',{name:'White',exact:true}).click();assert.equal(await native.inputValue(),'white');
  await page.setViewportSize({width:1200,height:900});
 }
 const fallback=await browser.newContext({ignoreHTTPSErrors:true,javaScriptEnabled:false});
 await fallback.route('**/__codex-category-add/',r=>r.fulfill({contentType:'text/html',body:readFileSync(dir+'/icts-category-add-fixture.html','utf8')}));
 const nojs=await fallback.newPage();await nojs.goto('https://iesaero.local/__codex-category-add/');assert.ok(await nojs.locator('select').isVisible());
 assert.deepEqual(errors,[]);
 console.log('PASS '+name+': add/edit, 31 coloured choices, mouse/keyboard, type-ahead, Escape, Tab, native form values, reset, list swatches, mobile bounds and no-JavaScript fallback');
 } finally {await browser.close();}
}
})().catch(e=>{console.error(e);process.exit(1)});
